import pandas as pd
from collections import Counter, defaultdict
from typing import List, Tuple

from solver import Algorithm


class Evolved(Algorithm):
    """Validity-preserving bounded optimizer for serialized Trie prefix reuse."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the dataframe reference and initialize shape bookkeeping."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _text(value) -> str:
        """Serialize one cell, mapping scalar missing values to an empty string."""
        try:
            missing = pd.isna(value)
            if isinstance(missing, bool) and missing:
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(a: str, b: str) -> int:
        """Compute a common-prefix length with binary search over string slices."""
        limit = min(len(a), len(b))
        if limit == 0 or a[0] != b[0]:
            return 0

        lo, hi = 1, limit
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if a[:mid] == b[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _reuse(cls, strings: List[str]) -> int:
        """Return exact sorted-adjacent serialized character-Trie reuse."""
        if len(strings) < 2:
            return 0

        ordered = sorted(strings)
        total = 0
        previous = ordered[0]

        for current in ordered[1:]:
            if current == previous:
                total += len(current)
            else:
                total += cls._lcp(previous, current)
            previous = current

        return total

    @staticmethod
    def _merge(columns, order, col_merge):
        """Keep requested column groups contiguous while preserving all columns."""
        if not col_merge:
            return list(order)

        position = {column: i for i, column in enumerate(order)}
        groups = {}
        claimed = set()

        for request in col_merge:
            members = [
                column for column in order
                if column in request and column not in claimed
            ]
            if not members:
                continue

            members.sort(key=position.__getitem__)
            for column in members:
                groups[column] = members
                claimed.add(column)

        result = []
        emitted = set()

        for column in order:
            if column in emitted:
                continue

            group = groups.get(column)
            if group is None:
                result.append(column)
                emitted.add(column)
            else:
                result.extend(group)
                emitted.update(group)

        return result

    @staticmethod
    def _strings(text, orders):
        """Serialize every row using its supplied source-column permutation."""
        return [
            "".join(text[row][column] for column in orders[row])
            for row in range(len(orders))
        ]

    def _normalize_order(self, columns, integer_order, col_merge):
        """Apply merge constraints and convert column labels back to positions."""
        names = self._merge(
            columns,
            [columns[index] for index in integer_order],
            col_merge,
        )
        lookup = {column: index for index, column in enumerate(columns)}
        return [lookup[name] for name in names]

    def _global_candidates(self, text, columns, col_merge):
        """Build singleton and repeated ordered-pair global column candidates."""
        n = len(text)
        m = len(columns)

        statistics = []
        for column in range(m):
            counts = Counter(text[row][column] for row in range(n))

            pair_mass = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            repeat_mass = sum(
                len(value) * (count - 1)
                for value, count in counts.items()
            )

            statistics.append(
                (pair_mass, repeat_mass, len(counts))
            )

        ranked = sorted(
            range(m),
            key=lambda column: (
                -statistics[column][0],
                -statistics[column][1],
                statistics[column][2],
                column,
            ),
        )

        # Candidate one: straightforward frequency-ranked columns.
        singleton = self._normalize_order(
            columns,
            ranked,
            col_merge,
        )

        # Candidate two: repeated ordered-pair prefix blocks.
        examined = ranked[:min(28, m)]
        pair_scores = []

        for first in examined:
            for second in examined:
                if first == second:
                    continue

                counts = Counter(
                    text[row][first] + text[row][second]
                    for row in range(n)
                )
                score = sum(
                    len(value) * count * (count - 1)
                    for value, count in counts.items()
                )

                if score > 0:
                    pair_scores.append((-score, first, second))

        pair_scores.sort()

        used = set()
        selected_pairs = []

        for negative_score, first, second in pair_scores:
            if first in used or second in used:
                continue

            selected_pairs.append((first, second))
            used.add(first)
            used.add(second)

        pair_order = [
            column
            for first, second in selected_pairs
            for column in (first, second)
        ]
        pair_order.extend(
            column for column in ranked
            if column not in used
        )

        pair_order = self._normalize_order(
            columns,
            pair_order,
            col_merge,
        )

        return (
            [singleton, pair_order],
            ranked,
            statistics,
        )

    def _conditional(self, text, columns, col_merge, global_order, statistics):
        """Build bounded row-specific orders by recursively grouping repeated values."""
        n = len(text)
        m = len(columns)
        result = [None] * n

        useful = [
            column for column in global_order
            if statistics[column][0] > 0
        ][:min(20, m)]
        useful_set = set(useful)

        max_depth = min(8, len(useful))
        node_limit = 384
        node_count = 0

        def complete(rows, prefix, remaining):
            """Assign a normalized global-tail order to a terminal row group."""
            tail = [
                column for column in global_order
                if column in remaining
            ]
            order = self._normalize_order(
                columns,
                prefix + tail,
                col_merge,
            )

            for row in rows:
                result[row] = order[:]

        def visit(rows, remaining, prefix, depth):
            """Split a row group on its best length-weighted repeated field."""
            nonlocal node_count
            node_count += 1

            branchable = [
                column for column in remaining
                if column in useful_set
            ]

            if (
                len(rows) < 2
                or not branchable
                or depth >= max_depth
                or node_count > node_limit
            ):
                complete(rows, prefix, remaining)
                return

            best_column = -1
            best_score = 0
            best_groups = None

            for column in branchable:
                groups = defaultdict(list)

                for row in rows:
                    groups[text[row][column]].append(row)

                score = sum(
                    len(value) * len(members) * (len(members) - 1)
                    for value, members in groups.items()
                    if len(members) > 1
                )

                if (
                    score > best_score
                    or (
                        score == best_score
                        and score > 0
                        and (
                            best_column < 0
                            or column < best_column
                        )
                    )
                ):
                    best_column = column
                    best_score = score
                    best_groups = groups

            if best_column < 0 or best_score <= 0:
                complete(rows, prefix, remaining)
                return

            rest = [
                column for column in remaining
                if column != best_column
            ]

            groups = sorted(
                best_groups.values(),
                key=lambda members: (-len(members), min(members)),
            )

            for members in groups:
                visit(
                    members,
                    rest,
                    prefix + [best_column],
                    depth + 1,
                )

        visit(list(range(n)), list(range(m)), [], 0)

        fallback = list(global_order)
        for row in range(n):
            if result[row] is None:
                result[row] = fallback[:]

        return result

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Select the best bounded global or conditional serialized prefix layout."""
        self.df = df
        self.num_rows, self.num_cols = df.shape

        n, m = df.shape
        columns = list(df.columns)

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)

        text = [
            [
                self._text(raw[row, column])
                for column in range(m)
            ]
            for row in range(n)
        ]

        global_orders, base_order, statistics = self._global_candidates(
            text,
            columns,
            col_merge,
        )

        candidates = []

        for order in global_orders:
            orders = [order[:] for _ in range(n)]
            serialized = self._strings(text, orders)
            candidates.append(
                (self._reuse(serialized), orders, serialized)
            )

        conditional_orders = self._conditional(
            text,
            columns,
            col_merge,
            base_order,
            statistics,
        )
        conditional_serialized = self._strings(
            text,
            conditional_orders,
        )
        candidates.append(
            (
                self._reuse(conditional_serialized),
                conditional_orders,
                conditional_serialized,
            )
        )

        _, best_orders, best_serialized = max(
            candidates,
            key=lambda candidate: candidate[0],
        )

        row_order = sorted(
            range(n),
            key=lambda row: best_serialized[row],
        )

        output = [
            [
                raw[row, column]
                for column in best_orders[row]
            ]
            for row in row_order
        ]

        orderings = [
            [
                columns[column]
                for column in best_orders[row]
            ]
            for row in row_order
        ]

        result = pd.DataFrame(
            output,
            columns=columns,
            index=df.index.take(row_order),
            dtype=object,
        )

        return result, orderings

