        while lo < hi:
            mid = (lo + hi + 1) // 2
            if a[:mid] == b[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _reuse(cls, strings: List[str]) -> int:
        """Score exact ideal character-Trie reuse via sorted adjacent serialized strings."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        total = 0
        previous = ordered[0]
        for current in ordered[1:]:
            if current == previous:
                total += len(current)
            else:
                total += cls._lcp(previous, current)
            previous = current
        return total

    @staticmethod
    def _merge(columns, order, col_merge):
        """Normalize an order while keeping each requested merge group contiguous."""
        if not col_merge:
            return list(order)

        position = {column: i for i, column in enumerate(order)}
        grouped = {}
        claimed = set()

        for request in col_merge:
            group = [
                column for column in order
                if column in request and column not in claimed
            ]
            if group:
                group.sort(key=position.__getitem__)
                for column in group:
                    grouped[column] = group
                    claimed.add(column)

        result = []
        emitted = set()
        for column in order:
            if column in emitted:
                continue
            group = grouped.get(column)
            if group is None:
                result.append(column)
                emitted.add(column)
            else:
                result.extend(group)
                emitted.update(group)
        return result

    @staticmethod
    def _strings(text, orders):
        """Serialize every row according to its row-specific source-column order."""
        return [
            "".join(text[row][column] for column in orders[row])
            for row in range(len(orders))
        ]

    def _global_candidates(self, text, columns, col_merge):
